<?php
require_once 'includes/config.php'; require_admin();
$class=(int)($_GET['class_id']??0);$year=trim((string)($_GET['academic_year']??''));$term=trim((string)($_GET['term']??''));$status=trim((string)($_GET['status']??''));$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$format=(string)($_GET['export']??'');
$where=[];$p=[];if($class){$where[]='f.class_id=:c';$p[':c']=$class;}if($year!==''){$where[]='f.academic_year=:y';$p[':y']=$year;}if($term!==''){$where[]='f.term=:t';$p[':t']=$term;}if($from!==''){$where[]='EXISTS(SELECT 1 FROM student_fee_payments px WHERE px.fee_id=f.id AND px.payment_date>=:from)';$p[':from']=$from;}if($to!==''){$where[]='EXISTS(SELECT 1 FROM student_fee_payments py WHERE py.fee_id=f.id AND py.payment_date<=:to)';$p[':to']=$to;}
$sql="SELECT f.id,f.student_id,f.academic_year,f.term,f.amount_due,s.StudentName,s.RollId,c.ClassName,c.Section,COALESCE(SUM(pay.amount),0) paid FROM student_term_fees f JOIN tblstudents s ON s.StudentId=f.student_id JOIN tblclasses c ON c.id=f.class_id LEFT JOIN student_fee_payments pay ON pay.fee_id=f.id".($where?' WHERE '.implode(' AND ',$where):'')." GROUP BY f.id,f.student_id,f.academic_year,f.term,f.amount_due,s.StudentName,s.RollId,c.ClassName,c.Section ORDER BY f.academic_year DESC,f.term,c.ClassName,s.StudentName";
$q=$dbh->prepare($sql);$q->execute($p);$rows=[];foreach($q->fetchAll() as $r){$r['balance']=max(0,(float)$r['amount_due']-(float)$r['paid']);$r['status']=$r['balance']<=0?'Fully Paid':((float)$r['paid']>0?'Partially Paid':'Unpaid');if($status!==''&&$r['status']!==$status)continue;$rows[]=$r;}
if($format==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="srms-fee-report.csv"');$o=fopen('php://output','w');fputcsv($o,['Student','Roll ID','Class','Academic Year','Term','Total Due','Total Paid','Balance','Payment Status']);foreach($rows as $r)fputcsv($o,[$r['StudentName'],$r['RollId'],$r['ClassName'].' '.$r['Section'],$r['academic_year'],$r['term'],$r['amount_due'],$r['paid'],$r['balance'],$r['status']]);fclose($o);exit;}
if($format==='xlsx'){if(!class_exists('PhpOffice\\PhpSpreadsheet\\Spreadsheet')){http_response_code(501);exit('XLSX export requires PhpSpreadsheet. Install with: composer require phpoffice/phpspreadsheet');}$book=new PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->fromArray([['Student','Roll ID','Class','Academic Year','Term','Total Due','Total Paid','Balance','Payment Status']],null,'A1');$i=2;foreach($rows as $r)$sheet->fromArray([[$r['StudentName'],$r['RollId'],$r['ClassName'].' '.$r['Section'],$r['academic_year'],$r['term'],(float)$r['amount_due'],(float)$r['paid'],(float)$r['balance'],$r['status']]],null,'A'.$i++);foreach(range('A','I') as $col)$sheet->getColumnDimension($col)->setAutoSize(true);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="srms-fee-report.xlsx"');(new PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;}
if($format==='pdf'){?><!doctype html><html><head><meta charset="utf-8"><title>SRMS Fee Report</title><style>body{font:12px Arial;margin:24px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:6px;text-align:left}button{padding:8px 16px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>School Fee Report</h1><p>Generated <?=e(date('Y-m-d H:i'))?></p><table><thead><tr><th>Student</th><th>Class</th><th>Year / Term</th><th>Due (MWK)</th><th>Paid (MWK)</th><th>Balance (MWK)</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['StudentName'].' ('.$r['RollId'].')')?></td><td><?=e($r['ClassName'].' '.$r['Section'])?></td><td><?=e($r['academic_year'].' / '.$r['term'])?></td><td><?=number_format($r['amount_due'],2)?></td><td><?=number_format($r['paid'],2)?></td><td><?=number_format($r['balance'],2)?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></body></html><?php exit;}
$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassName,Section')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee Reports | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container srms-page"><p><a href="manage-fees.php">← Fees Management</a></p><h2>Financial Reports & Historical Spooling</h2><p class="text-muted">All fee amounts are shown in Malawi Kwacha (MWK).</p><form method="get" class="panel panel-default panel-body row"><div class="col-md-3 form-group"><label>Class/Form</label><select class="form-control" name="class_id"><option value="0">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class===(int)$c['id']?'selected':''?>><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Academic year</label><input name="academic_year" class="form-control" value="<?=e($year)?>"></div><div class="col-md-2 form-group"><label>Term</label><input name="term" class="form-control" value="<?=e($term)?>"></div><div class="col-md-2 form-group"><label>Status</label><select name="status" class="form-control"><option value="">All</option><?php foreach(['Fully Paid','Partially Paid','Unpaid'] as $s):?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Payment from</label><input type="date" name="from" value="<?=e($from)?>" class="form-control"></div><div class="col-md-2 form-group"><label>Payment to</label><input type="date" name="to" value="<?=e($to)?>" class="form-control"></div><div class="col-md-12"><button class="btn btn-primary">Filter</button> <button class="btn btn-default" name="export" value="csv">Export CSV</button> <button class="btn btn-default" name="export" value="xlsx">Export Excel (.xlsx)</button> <button class="btn btn-default" name="export" value="pdf">Print / Save PDF</button></div></form><div class="row"><div class="col-sm-4"><div class="well">Total Due (MWK) <h3><?=number_format(array_sum(array_column($rows,'amount_due')),2)?></h3></div></div><div class="col-sm-4"><div class="well">Total Collected (MWK) <h3><?=number_format(array_sum(array_column($rows,'paid')),2)?></h3></div></div><div class="col-sm-4"><div class="well">Outstanding (MWK) <h3><?=number_format(array_sum(array_column($rows,'balance')),2)?></h3></div></div></div><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Student</th><th>Class</th><th>Year / Term</th><th>Due (MWK)</th><th>Paid (MWK)</th><th>Balance (MWK)</th><th>Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['StudentName'].' — '.$r['RollId'])?></td><td><?=e($r['ClassName'].' '.$r['Section'])?></td><td><?=e($r['academic_year'].' / '.$r['term'])?></td><td><?=number_format($r['amount_due'],2)?></td><td><?=number_format($r['paid'],2)?></td><td><?=number_format($r['balance'],2)?></td><td><?=e($r['status'])?></td><td><a href="fee-student-workspace.php?student_id=<?=$r['student_id']?>">Open ledger</a></td></tr><?php endforeach;?></tbody></table></div></div></main></div></div></div></div></body></html>
